// FlutterFlow custom widget BODY TEMPLATE. Not a standalone package.
 // Add the package import *below* FlutterFlow's autogenerated imports:
 // import 'package:aya_flutter/aya_flutter.dart';
 //
 // Register a custom widget named AyaFlutterFlowHelpWidget and the parameters:
 // width, height (nullable Double); description, attachmentDisclosure,
 // outputInstructions (required String); screenName (nullable String).
 // Preserve FlutterFlow's own generated header/imports when pasting.

class AyaFlutterFlowHelpWidget extends StatelessWidget {
  const AyaFlutterFlowHelpWidget({
    super.key,
    this.width,
    this.height,
    required this.description,
    required this.attachmentDisclosure,
    required this.outputInstructions,
    this.screenName,
  });

  final double? width;
  final double? height;
  final String description;
  final String attachmentDisclosure;
  final String outputInstructions;
  final String? screenName;

  @override
  Widget build(BuildContext context) {
    // A minimum, rather than fixed height, avoids clipping during font scaling.
    // The page owns scrolling. The underlying card never monitors the AI app.
    return ConstrainedBox(
      constraints: BoxConstraints(minHeight: height ?? 0),
      child: SizedBox(
        width: width,
        child: AyaHelpCard(
          description: description,
          attachmentDisclosure: attachmentDisclosure,
          outputInstructions: outputInstructions,
          screenName: screenName,
        ),
      ),
    );
  }
}
